/* Host test of fbl_law.c against the authors' code (law_vectors_*.txt, generated by gen_law_vectors.py). make test_law */
#include "fbl_law.h"
#include <math.h>
#include <stdio.h>
#include <string.h>

static int fails = 0;
#define CHECK(c, ...) do { if (!((c))) { fails++; printf("FAIL: " __VA_ARGS__); printf("\n"); } } while (0)
static void upd(double *worst, double err, double atol, double ref) { const double r = err / (atol + 2e-5 * fabs(ref)); if (r > *worst) { *worst = r; } }

int main(void)
{
  fbl_gains_t g; fbl_gains_default_bundle(&g);
  FILE *f = fopen("law_vectors_command.txt", "r");
  if (!f) { printf("law_vectors_command.txt missing: run gen_law_vectors.py\n"); return 2; }
  int n; if (fscanf(f, "%d", &n) != 1) return 2;
  double wt = 0, ww = 0, wq = 0, max_thrust = 0, max_w = 0, max_tau = 0; int skipped = 0, floor_cases = 0;
  for (int k = 0; k < n; k++) {
    float R[9], w[3], acc[3], jerk[3], yaw, yr, ra[3], rj[3], rw[3], th_e, wd_e[3], tau_e[3];
    float *p[] = {R, w, acc, jerk, &yaw, &yr, ra, rj, rw, &th_e, wd_e, tau_e}; const int len[] = {9, 3, 3, 3, 1, 1, 3, 3, 3, 1, 3, 3};
    for (int b = 0; b < 12; b++) for (int i = 0; i < len[b]; i++) if (fscanf(f, "%f", &p[b][i]) != 1) return 2;
    float th, wd[3], tau[3]; fbl_law_command(R, w, acc, jerk, yaw, yr, ra, rj, rw, &g, &th, wd, tau);
    /* near the yaw singularity (|denominator| < 1e-2: body x axis almost perpendicular to the heading, i.e. about +-90 deg tilt) the yaw rate is ill-conditioned
       (relative error of the denominator 1e-7 / 1e-3), float and double legitimately differ: counted, not compared */
    { const float den = R[0] * cosf(yaw) + R[3] * sinf(yaw); if (fabsf(den) < 1e-2f) { skipped++; continue; } }
    if (th_e < 0.01f) floor_cases++;
    upd(&wt, fabs((double)th - th_e), 1e-6, th_e); if (fabs((double)th - th_e) > max_thrust) max_thrust = fabs((double)th - th_e);
    for (int i = 0; i < 3; i++) {
      upd(&ww, fabs((double)wd[i] - wd_e[i]), 1e-4, wd_e[i]); if (fabs((double)wd[i] - wd_e[i]) > max_w) max_w = fabs((double)wd[i] - wd_e[i]);
      upd(&wq, fabs((double)tau[i] - tau_e[i]), 1e-8, tau_e[i]); if (fabs((double)tau[i] - tau_e[i]) > max_tau) max_tau = fabs((double)tau[i] - tau_e[i]);
    }
  }
  fclose(f);
  printf("command: %d cases (%d near the yaw singularity not compared, %d with thrust below the 0.01 N floor compared)\n  thrust: max abs error %.2e N, worst error / tolerance %.3f (1e-6 + 2e-5|ref|)\n  body rates: max abs error %.2e rad/s, worst %.3f (1e-4 + 2e-5|ref|)\n  torque: max abs error %.2e N m, worst %.3f (1e-8 + 2e-5|ref|)\n", n, skipped, floor_cases, max_thrust, wt, max_w, ww, max_tau, wq);
  CHECK(wt <= 1.0 && ww <= 1.0 && wq <= 1.0, "command outside the tolerance");

  f = fopen("law_vectors_position.txt", "r");
  if (!f) { printf("law_vectors_position.txt missing\n"); return 2; }
  int nseq, nstep; if (fscanf(f, "%d %d", &nseq, &nstep) != 2) return 2;
  double wa = 0, wj = 0, max_a = 0, max_j = 0;
  for (int s = 0; s < nseq; s++) {
    fbl_law_state_t st; fbl_law_reset(&st);
    for (int i = 0; i < nstep; i++) {
      float t, pos[3], vel[3]; fbl_ref_t ref; float ea[3], ej[3];
      float *p[] = {&t, pos, vel, ref.x, ref.x_dot, ref.x_ddot, ref.x_dddot, ea, ej}; const int len[] = {1, 3, 3, 3, 3, 3, 3, 3, 3};
      for (int b = 0; b < 9; b++) for (int k = 0; k < len[b]; k++) if (fscanf(f, "%f", &p[b][k]) != 1) return 2;
      float acc[3], jerk[3]; fbl_law_position(&st, &g, t, pos, vel, &ref, acc, jerk);
      for (int k = 0; k < 3; k++) {
        upd(&wa, fabs((double)acc[k] - ea[k]), 1e-3, ea[k]); upd(&wj, fabs((double)jerk[k] - ej[k]), 1e-2, ej[k]);
        if (fabs((double)acc[k] - ea[k]) > max_a) { max_a = fabs((double)acc[k] - ea[k]); }
        if (fabs((double)jerk[k] - ej[k]) > max_j) { max_j = fabs((double)jerk[k] - ej[k]); }
      }
    }
  }
  fclose(f);
  printf("position law: %d sequences x %d steps (alpha-beta-gamma estimate, integral, repeated time stamps)\n  acceleration command: max abs error %.2e m/s^2, worst error / tolerance %.3f (1e-3 + 2e-5|ref|)\n  jerk command: max abs error %.2e m/s^3, worst %.3f (1e-2 + 2e-5|ref|)\n", nseq, nstep, max_a, wa, max_j, wj);
  CHECK(wa <= 1.0 && wj <= 1.0, "position law outside the tolerance");
  printf(fails ? "RESULT: %d FAILURES\n" : "RESULT: ALL PASSED\n", fails);
  return fails ? 1 : 0;
}
